let $c := /FundsXML4/ControlData return (
  if (empty($c)) then local:at(/*, 'ControlData is missing') else (),
  for $p in ('UniqueDocumentID', 'DocumentGenerated', 'ContentDate')
  where exists($c) and empty($c/*[local-name() = $p])
  return local:at($c, 'ControlData/' || $p || ' is missing'),
  if (exists($c) and empty($c/DataSupplier/Name)) then local:at(($c/DataSupplier, $c)[1], 'ControlData/DataSupplier/Name is missing') else ())

for $d in /FundsXML4/ControlData/ContentDate[. castable as xs:date]
where xs:date($d) gt current-date()
return local:at($d, 'ContentDate ' || $d || ' is in the future')

(for $c in //*[local-name() = ('Currency', 'CurrencyBuy', 'CurrencySell', 'PriceCurrency', 'SettlementCurrency')][not(*)]
  [not(matches(normalize-space(.), '^[A-Z]{3}$'))]
  return local:at($c, local:where($c) || ': ' || local-name($c) || ' ' || $c || ' is no ISO 4217 code'),
 for $a in //@ccy[not(matches(., '^[A-Z]{3}$'))]
  return local:at($a, local:where($a) || ': ccy=' || $a || ' is no ISO 4217 code'))

for $ps in //Portfolios[Portfolio/Positions/Position/TotalPercentage], $d in distinct-values($ps/Portfolio/NavDate)
let $sum := sum($ps/Portfolio[NavDate = $d]/Positions/Position/TotalPercentage ! local:dec(.))
where abs($sum - 100) gt 0.5
return local:at(($ps/Portfolio[NavDate = $d])[1], local:owner($ps) || ', ' || $d || ': the position weights add up to ' || $sum || ' %')

for $ps in //Portfolios[Portfolio/Positions/Position], $d in distinct-values($ps/Portfolio/NavDate)
let $ccy := local:owner-ccy($ps)
let $tna := local:dec(($ps/../TotalAssetValues/TotalAssetValue[NavDate = $d]/TotalNetAssetValue/Amount[@ccy = $ccy])[1])
let $sum := sum($ps/Portfolio[NavDate = $d]/Positions/Position/TotalValue/Amount[@ccy = $ccy] ! local:dec(.))
where exists($tna) and $tna ne 0 and abs($sum - $tna) div abs($tna) gt 0.01
return local:at(($ps/Portfolio[NavDate = $d])[1], local:owner($ps) || ', ' || $d || ': positions add up to ' || $sum || ' ' || $ccy || ', the net asset value is ' || $tna || ' ' || $ccy || ' (' || round(($sum - $tna) div $tna * 100, 2) || ' %)')

for $ps in //Portfolios/Portfolio/Positions, $id in distinct-values($ps/Position/UniqueID)
where count($ps/Position[UniqueID = $id]) gt 1
return local:at($ps/Position[UniqueID = $id][2], local:fund($ps) || ': position ' || $id || ' appears ' || count($ps/Position[UniqueID = $id]) || ' times')

let $used := (//Portfolios/Portfolio/Positions/Position/UniqueID, //Transaction/AssetUniqueID, //Earning/AssetUniqueID)
for $a in /FundsXML4/AssetMasterData/Asset[not(UniqueID = $used)]
return local:at($a, 'Asset ' || $a/UniqueID || ' (' || $a/Name || ') is not used by any position, transaction or earning')

for $pos in //Portfolios/Portfolio/Positions/Position[Equity or Bond or ShareClass or Certificate or Warrant]
let $v := local:dec(($pos/TotalValue/Amount)[1])
where exists($v) and $v lt 0
return local:at($pos, 'Position ' || $pos/UniqueID || ' has a negative value: ' || $v)

for $f in //Funds/Fund[SingleFund/ShareClasses/ShareClass/TotalAssetValues]
let $ccy := string($f/Currency)
for $tav in $f/FundDynamicData/TotalAssetValues/TotalAssetValue
let $d := $tav/NavDate
let $tna := local:dec(($tav/TotalNetAssetValue/Amount[@ccy = $ccy])[1])
let $classes := $f/SingleFund/ShareClasses/ShareClass/TotalAssetValues/TotalAssetValue[NavDate = $d]/TotalNetAssetValue/Amount[@ccy = $ccy]
let $sum := sum($classes ! local:dec(.))
where exists($tna) and exists($classes) and $tna ne 0 and abs($sum - $tna) div abs($tna) gt 0.005
return local:at($tav, local:fund($f) || ', ' || $d || ': share classes add up to ' || $sum || ' ' || $ccy || ', the fund has ' || $tna || ' ' || $ccy)

for $sc in //ShareClass[Prices/Price and TotalAssetValues/TotalAssetValue]
for $tav in $sc/TotalAssetValues/TotalAssetValue
let $price := $sc/Prices/Price[NavDate = $tav/NavDate][1]
let $p := local:dec(($price/NavPrice)[1])
let $shares := local:dec(($tav/SharesOutstanding)[1])
let $tna := local:dec(($tav/TotalNetAssetValue/Amount[@ccy = $price/PriceCurrency], $tav/TotalNetAssetValue/Amount)[1])
where exists($p) and exists($shares) and exists($tna) and $tna ne 0 and abs($p * $shares - $tna) div abs($tna) gt 0.01
return local:at($tav, 'Share class ' || ($sc/Identifiers/ISIN, $sc/Names/OfficialName)[1] || ', ' || $tav/NavDate || ': ' || $p || ' × ' || $shares || ' = ' || round($p * $shares, 2) || ', the net asset value is ' || $tna)

for $t in //Transaction[ValutaDate castable as xs:date and EntryDate castable as xs:date]
where xs:date($t/ValutaDate) lt xs:date($t/EntryDate)
return local:at($t, 'Transaction ' || $t/TransactionID || ': ValutaDate ' || $t/ValutaDate || ' is before EntryDate ' || $t/EntryDate)

let $content := /FundsXML4/ControlData/ContentDate[. castable as xs:date] ! xs:date(.)
where exists($content)
return for $a in /FundsXML4/AssetMasterData/Asset[AssetDetails/*/MaturityDate castable as xs:date]
       let $m := xs:date(($a/AssetDetails/*/MaturityDate)[1])
       where $m lt $content and $a/UniqueID = //Portfolios/Portfolio/Positions/Position/UniqueID
       return local:at($a, 'Asset ' || $a/UniqueID || ' (' || $a/Name || ') matured on ' || $m || ' but is still held')

for $pos in //Portfolios/Portfolio/Positions/Position
let $ccy := local:owner-ccy($pos)
where $ccy ne '' and not($pos/TotalValue/Amount/@ccy = $ccy)
return local:at($pos, local:owner($pos) || ': position ' || $pos/UniqueID || ' has no TotalValue in ' || $ccy)

for $tav in //TotalAssetValues/TotalAssetValue[TotalNetAssetValue/Amount]
let $ccy := local:owner-ccy($tav)
where $ccy ne '' and not($tav/TotalNetAssetValue/Amount/@ccy = $ccy)
return local:at($tav, local:owner($tav) || ', ' || $tav/NavDate || ': the net asset value is not given in ' || $ccy)

let $assets := /FundsXML4/AssetMasterData/Asset
for $id in distinct-values($assets/UniqueID)
let $same := $assets[UniqueID = $id]
where count($same) gt 1
return local:at($same[2], 'Asset ' || $id || ' appears ' || count($same) || ' times in AssetMasterData')

let $assets := /FundsXML4/AssetMasterData/Asset[Identifiers/ISIN]
for $isin in distinct-values($assets/Identifiers/ISIN ! normalize-space(.))
let $same := $assets[Identifiers/ISIN ! normalize-space(.) = $isin]
where count($same) gt 1
return local:at($same[2], 'ISIN ' || $isin || ' belongs to ' || count($same) || ' assets: ' || string-join($same/UniqueID, ', '))

let $isins := map:merge(for $a in /FundsXML4/AssetMasterData/Asset[Identifiers/ISIN]
                        return map { string($a/UniqueID): normalize-space($a/Identifiers/ISIN[1]) },
                        map { 'duplicates': 'use-first' })
for $pos in //Portfolios/Portfolio/Positions/Position[Identifiers/ISIN]
let $own := normalize-space($pos/Identifiers/ISIN[1])
let $master := $isins(string($pos/UniqueID))
where exists($master) and $own ne $master
return local:at($pos/Identifiers/ISIN[1], 'Position ' || $pos/UniqueID || ': ISIN ' || $own || ', the asset has ISIN ' || $master)

for $ts in //Transactions
let $live := $ts/Transaction[not(CancellationFlag = ('true', '1'))]
for $id in distinct-values($live/TransactionID)
let $same := $live[TransactionID = $id]
where count($same) gt 1
return local:at($same[2], local:owner($ts) || ': transaction ' || $id || ' appears ' || count($same) || ' times')

for $c in //*[local-name() = ('Country', 'SystemCountry', 'BusinessCountry', 'CountryCode', 'CountryOfDomicile',
                              'DomicileCountry', 'FundCustodianCountry', 'InvestorCountry', 'IssuerCountry',
                              'ListOfInvestedCountries')][not(*)][normalize-space(.) ne '']
             [not(matches(normalize-space(.), '^[A-Z]{2}$'))]
return local:at($c, local:where($c) || ': ' || local-name($c) || ' ' || $c || ' is no ISO 3166 code')

for $c in /FundsXML4/ControlData[DocumentGenerated castable as xs:dateTime]
let $generated := xs:date(substring($c/DocumentGenerated, 1, 10))
let $content := $c/ContentDate[. castable as xs:date] ! xs:date(.)
return (
  if (exists($content) and $generated lt $content)
  then local:at($c/DocumentGenerated, 'DocumentGenerated ' || $c/DocumentGenerated || ' is before the ContentDate ' || $content) else (),
  if ($generated gt current-date())
  then local:at($c/DocumentGenerated, 'DocumentGenerated ' || $c/DocumentGenerated || ' is in the future') else ())

let $content := /FundsXML4/ControlData/ContentDate[. castable as xs:date] ! xs:date(.)
where exists($content)
return for $d in //NavDate[. castable as xs:date][xs:date(.) gt $content]
       return local:at($d, local:owner($d) || ': ' || local-name($d/..) || ' of ' || $d || ' is after the ContentDate ' || $content)

for $d in //NavDate[. castable as xs:date]
let $o := local:owner-node($d)
let $inception := ($o/InceptionDate, $o/*[ends-with(local-name(), 'StaticData')]/InceptionDate)[. castable as xs:date][1]
where exists($inception) and xs:date($d) lt xs:date($inception)
return local:at($d, local:owner($d) || ': ' || local-name($d/..) || ' of ' || $d || ' is before the InceptionDate ' || $inception)

for $b in /FundsXML4/AssetMasterData/Asset/AssetDetails/Bond[MaturityDate castable as xs:date and IssueDate castable as xs:date]
where xs:date($b/MaturityDate) lt xs:date($b/IssueDate)
return local:at($b, 'Asset ' || $b/../../UniqueID || ' (' || $b/../../Name || '): MaturityDate ' || $b/MaturityDate || ' is before IssueDate ' || $b/IssueDate)

for $e in //Earning[ValutaDate castable as xs:date and EntryDate castable as xs:date]
where xs:date($e/ValutaDate) lt xs:date($e/EntryDate)
return local:at($e, 'Earning ' || $e/EarningID || ': ValutaDate ' || $e/ValutaDate || ' is before EntryDate ' || $e/EntryDate)

let $content := /FundsXML4/ControlData/ContentDate[. castable as xs:date] ! xs:date(.)
where exists($content)
return for $t in //Transaction[EntryDate castable as xs:date][xs:date(EntryDate) gt $content]
       return local:at($t, 'Transaction ' || $t/TransactionID || ': EntryDate ' || $t/EntryDate || ' is after the ContentDate ' || $content)

for $pos in //Portfolios/Portfolio/Positions/Position, $s in $pos/(Equity | ShareClass)
let $units := local:dec(($s/Units, $s/Shares)[1])
let $pairs := for $p in $s/Price/Amount
              let $mv := ($s/MarketValue/Amount[@ccy = $p/@ccy])[1]
              where exists(local:dec($p)) and exists(local:dec($mv)) and local:dec($mv) ne 0
              return map { 'price': local:dec($p), 'value': local:dec($mv), 'ccy': string($p/@ccy) }
let $pair := $pairs[1]
where exists($units) and exists($pair) and abs($units * $pair?price - $pair?value) div abs($pair?value) gt 0.01
return local:at($s, 'Position ' || $pos/UniqueID || ': ' || $units || ' × ' || $pair?price || ' = ' || round($units * $pair?price, 2) || ' ' || $pair?ccy || ', the market value is ' || $pair?value || ' ' || $pair?ccy)

for $p in //Portfolios/Portfolio[Positions/Position/TotalPercentage]
let $ccy := local:owner-ccy($p)
let $tna := local:dec(($p/../../TotalAssetValues/TotalAssetValue[NavDate = $p/NavDate]/TotalNetAssetValue/Amount[@ccy = $ccy])[1])
where exists($tna) and $tna ne 0
return for $pos in $p/Positions/Position
       let $pct := local:dec($pos/TotalPercentage)
       let $value := local:dec(($pos/TotalValue/Amount[@ccy = $ccy])[1])
       let $calc := $value div $tna * 100
       where exists($pct) and exists($value) and abs($calc - $pct) gt 0.1
       return local:at($pos/TotalPercentage, local:owner($p) || ', ' || $p/NavDate || ': position ' || $pos/UniqueID || ' has ' || $pct || ' %, its value is ' || round($calc, 2) || ' % of the net asset value')

for $p in //Portfolios/Portfolio
let $rates := $p/Positions/Position/FXRates/FXRate
for $pair in distinct-values($rates ! (@fromCcy || '→' || @toCcy || ' (' || @mulDiv || ')'))
let $same := $rates[@fromCcy || '→' || @toCcy || ' (' || @mulDiv || ')' = $pair]
let $values := distinct-values($same ! local:dec(.))
where count($values) gt 1
return local:at($same[local:dec(.) ne $values[1]][1], local:owner($p) || ', ' || $p/NavDate || ': ' || $pair || ' is used with ' || count($values) || ' rates: ' || string-join($values ! string(.), ', '))

for $pos in //Portfolios/Portfolio/Positions/Position
let $v := $pos/TotalValue/Amount ! local:dec(.)
where some $x in $v satisfies $x gt 0 and (some $y in $v satisfies $y lt 0)
return local:at($pos, 'Position ' || $pos/UniqueID || ' has positive and negative values: ' || string-join($pos/TotalValue/Amount ! (. || ' ' || @ccy), ', '))

for $f in //Funds/Fund[SingleFund/ShareClasses/ShareClass/TotalAssetValues/TotalAssetValue/Ratio]
let $tavs := $f/SingleFund/ShareClasses/ShareClass/TotalAssetValues/TotalAssetValue
for $d in distinct-values($tavs/NavDate)
let $day := $tavs[NavDate = $d]
let $sum := sum($day/Ratio ! local:dec(.))
where every $t in $day satisfies exists(local:dec($t/Ratio))
  and abs($sum - 100) gt 0.5
return local:at($day[1], local:fund($f) || ', ' || $d || ': the share class ratios add up to ' || $sum || ' %')

(for $p in //Prices/Price/NavPrice[local:dec(.) le 0]
  return local:at($p, local:owner($p) || ', ' || $p/../NavDate || ': NAV price ' || $p),
 for $s in //TotalAssetValue/SharesOutstanding[local:dec(.) lt 0]
  return local:at($s, local:owner($s) || ', ' || $s/../NavDate || ': shares outstanding ' || $s),
 for $a in //TotalAssetValue/TotalNetAssetValue/Amount[local:dec(.) lt 0]
  return local:at($a, local:owner($a) || ', ' || $a/../../NavDate || ': net asset value ' || $a || ' ' || $a/@ccy))

for $ps in //Prices
for $k in distinct-values($ps/Price ! (NavDate || ' ' || PriceNature || ' ' || PriceCurrency))
let $same := $ps/Price[NavDate || ' ' || PriceNature || ' ' || PriceCurrency = $k]
where count($same) gt 1
return local:at($same[2], local:owner($ps) || ': ' || count($same) || ' prices for ' || normalize-space($k))

for $sc in //ShareClass[Currency and Prices/Price/PriceCurrency]
for $d in distinct-values($sc/Prices/Price/NavDate)
let $prices := $sc/Prices/Price[NavDate = $d]
where not($prices/PriceCurrency = $sc/Currency)
return local:at($prices[1], local:owner($sc) || ', ' || $d || ': no price in ' || $sc/Currency || ' (only ' || string-join(distinct-values($prices/PriceCurrency), ', ') || ')')

let $ccys := map:merge(for $a in /FundsXML4/AssetMasterData/Asset[Currency]
                       return map { string($a/UniqueID): string($a/Currency) },
                       map { 'duplicates': 'use-first' })
for $pos in //Portfolios/Portfolio/Positions/Position[Currency]
let $master := $ccys(string($pos/UniqueID))
where exists($master) and string($pos/Currency) ne $master
return local:at($pos/Currency, 'Position ' || $pos/UniqueID || ': currency ' || $pos/Currency || ', the asset has ' || $master)

for $fx in /FundsXML4/AssetMasterData/Asset/AssetDetails/FXForward
let $id := 'Asset ' || $fx/../../UniqueID || ' (' || $fx/../../Name || ')'
let $buy := local:dec($fx/AmountBuy)
let $sell := local:dec($fx/AmountSell)
let $rate := local:dec($fx/AgreedFxRate)
return (
  if ($fx/CurrencyBuy and string($fx/CurrencyBuy) eq string($fx/CurrencySell))
  then local:at($fx, $id || ': buys and sells ' || $fx/CurrencyBuy) else (),
  if ((exists($buy) and $buy le 0) or (exists($sell) and $sell le 0))
  then local:at($fx, $id || ': AmountBuy ' || $buy || ' and AmountSell ' || $sell || ' must be positive') else (),
  if (exists($buy) and exists($sell) and exists($rate) and $buy gt 0 and $sell gt 0 and $rate gt 0
      and abs($buy div $sell - $rate) div $rate gt 0.01 and abs($sell div $buy - $rate) div $rate gt 0.01)
  then local:at($fx, $id || ': agreed rate ' || $rate || ', the amounts give ' || round($buy div $sell, 6) || ' (or ' || round($sell div $buy, 6) || ')') else ())

(for $f in //Funds/Fund[not(Identifiers/LEI)]
  return local:at($f, local:fund($f) || ' has no LEI'),
 for $sc in //ShareClasses/ShareClass[not(Identifiers/ISIN)]
  return local:at($sc, local:owner($sc) || ' has no ISIN'))

for $pos in //Portfolios/Portfolio/Positions/Position[TotalValue/Amount]
where every $a in $pos/TotalValue/Amount satisfies local:dec($a) = 0
return local:at($pos, 'Position ' || $pos/UniqueID || ' has a value of 0')

let $content := /FundsXML4/ControlData/ContentDate[. castable as xs:date] ! xs:date(.)
where exists($content)
return for $ps in //Portfolios[Portfolio/NavDate[. castable as xs:date]]
       let $latest := max($ps/Portfolio/NavDate[. castable as xs:date] ! xs:date(.))
       where $content - $latest gt xs:dayTimeDuration('P31D')
       return local:at(($ps/Portfolio[NavDate = string($latest)], $ps)[1], local:owner($ps) || ': the latest portfolio is of ' || $latest || ', ' || days-from-duration($content - $latest) || ' days before the ContentDate')

snippets.query:
let $assets := /FundsXML4/AssetMasterData/Asset
for $p in (//FundDynamicData | //SubfundDynamicData)/Portfolios/Portfolio
let $pos := $p/Positions/Position[Equity or Bond or ShareClass or Certificate or Warrant][TotalPercentage castable as xs:decimal]
let $issuers := for $x in $pos
                let $a := $assets[UniqueID = $x/UniqueID][1]
                return map { 'issuer': string(($a/AssetDetails/*/Issuer/Identifiers/LEI, $a/AssetDetails/*/Issuer/Name, $a/Name, $x/UniqueID)[1]),
                             'weight': xs:decimal($x/TotalPercentage) }
let $byIssuer := for $i in distinct-values($issuers ! ?issuer)
                 return map { 'issuer': $i, 'weight': sum($issuers[?issuer = $i] ! ?weight) }
let $over5 := sum($byIssuer[?weight gt 5] ! ?weight)
return (
  ($p/ancestor::*[self::Fund or self::Subfund][1]/Names/OfficialName)[1] || ', ' || $p/NavDate || ': issuers over 5 % add up to ' || $over5 || ' %' || (if ($over5 gt 40) then ' (over the 40 % limit)' else ''),
  for $i in $byIssuer[?weight gt 10] order by $i?weight descending
  return '  ' || $i?issuer || ': ' || $i?weight || ' % (over the 10 % limit)')
